const evCard=(i,k,n)=>{const e=CATS[i].ev[k];return `<div class="sub" style="--i:${n??k}">${e.g?`<small>${e.g.toUpperCase()}</small>`:""}<h4>${e.n}</h4>${e.f?`<div class="feetag">Entry fee ${e.f[0]} <span>${e.f[1]}</span></div>`:""}${e.d?`<div class="evdt"><div><i>Date</i><b>${e.d}</b></div>${e.tm?`<div><i>Time</i><b>${e.tm}</b></div>`:""}</div>`:""}<div class="row"><a class="btn" href="#" data-reg data-ev="${e.n}">Register</a><button class="btn alt" data-det="${i}-${k}">Details</button></div></div>`};
const catHTML=i=>{const c=CATS[i];return `<div class="subhead">${c.n} events</div><div class="subs">`+c.ev.map((e,k)=>evCard(i,k)).join("")+"</div>"};
