 if(e.target.closest('nav a[href="#events"],.fnav a[href="#events"]'))openAll();
 if(!e.target.closest("#more"))menu(false);
 const rg=e.target.closest("[data-reg]");if(rg&&!GFORM_URL){e.preventDefault();toast("The registration Google Form link will be added here soon")}
