function cd(){let s=Math.max(0,(T-new Date())/1000|0);const v=[["DAYS",s/86400|0],["HOURS",s/3600%24|0],["MINS",s/60%60|0],["SECS",s%60]];
 $("#cd").innerHTML=s?v.map(x=>`<div><b>${String(x[1]).padStart(2,"0")}</b><small>${x[0]}</small></div>`).join(""):"<div style='padding:10px 20px'>The fest is live!</div>"}
